.author__name { margin: 0; font-size: 1.15rem; }
.author__role { margin: 0.25rem 0 0; font-size: 0.9rem; color: var(--cms-color-text-muted); }
.author__bio { margin-top: 0.75rem; color: var(--cms-color-text-muted); }
