.author__link a { color: var(--cms-color-accent-strong); font-weight: 600; text-underline-offset: 0.2em; transition: color 0.2s ease; }
.author__link a:hover, .author__link a:focus-visible { color: var(--cms-color-accent); }
@media (min-width: 48rem) { .author { padding: 1.75rem; } .author__body { gap: 1.5rem; } .author__photo { flex-basis: 6rem; } .author__img { width: 6rem; height: 6rem; } }"}
